using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<int> a(n), b(m);
    bool inA[10] = {}, inB[10] = {};

    for (int &x : a) {
        cin >> x;
        inA[x] = true;
    }
    for (int &x : b) {
        cin >> x;
        inB[x] = true;
    }

    for (int d = 1; d <= 9; ++d) {
        if (inA[d] && inB[d]) {
            cout << d;
            return 0;
        }
    }

    int x = *min_element(a.begin(), a.end());
    int y = *min_element(b.begin(), b.end());

    cout << min(x, y) * 10 + max(x, y);
    return 0;
}

